media:
@media (width >= 72rem) {
  .right-sidebar-container > .right-sidebar { border-inline-start: 0px; }
  [data-has-sidebar]:not([data-has-toc]):not([data-has-hero]) .main-pane { --sl-content-margin-inline: auto 0; width: min(calc(100% - var(--sl-sidebar-width)), calc(var(--sl-content-width) + (100% - var(--sl-content-width) - var(--sl-sidebar-width)) / 2)); }
}

@media (width >= 50rem) {
  .ltdm-header:where(.astro-nen7h5rs) { grid-template-columns: calc(var(--sl-sidebar-width) - var(--sl-nav-pad-x) - var(--sl-sidebar-pad-x)) 1fr auto; gap: var(--ltdm-header-gap); }
}

@media (width >= 50rem) {
  [data-has-sidebar] .header:where(.astro-7pllvep4) { padding-inline-end: var(--sl-nav-pad-x); }
  .sidebar-pane:where(.astro-7pllvep4) { --sl-sidebar-visibility: visible; width: var(--sl-sidebar-width); background-color: var(--sl-color-bg-sidebar); border-inline-end: 1px solid var(--sl-color-hairline-shade); }
  [data-has-sidebar] .header:where(.astro-7pllvep4)::before { content: ""; background-color: var(--sl-color-hairline-shade); width: 1px; position: absolute; inset-block: 0px; inset-inline-start: calc(var(--sl-sidebar-width) - 1px); }
}
